export const rrfAnswer: GroundedAnswer = { query: "How does reciprocal rank fusion work, and when should I use it?", blocks: [ { kind: "prose", id: "b0", text: "Reciprocal Rank Fusion (RRF) merges several ranked result lists into one. For each document it sums 1/(k + rank) over every list the document appears in, where k is a small constant (commonly 60) [[rrf_p0]]. Because the score depends only on a document's *position* in each list and never on raw scores, RRF can fuse fundamentally different retrieval methods — say BM25 and dense-vector search — without any score normalization [[elastic_p0]].", cited_passage_ids: ["rrf_p0", "elastic_p0"], }, { kind: "heading", id: "h1", text: "The formula", level: 2 }, { kind: "code", id: "b1", language: "python", code: "def rrf(rank_lists, k=60):
 scores = {}
 for ranks in rank_lists:
 for rank, doc in enumerate(ranks):
 scores[doc] = scores.get(doc, 0) + 1 / (k + rank)
 return sorted(scores, key=scores.get, reverse=True)", }, { kind: "callout", id: "b2", tone: "definition", title: "Why rank, not score?", text: "Raw relevance scores from BM25 and a vector index live on incompatible scales. Ranks are comparable across methods, so fusing on rank sidesteps normalization entirely.", }, { kind: "heading", id: "h2", text: "When to use it", level: 2 }, { kind: "prose", id: "b3", text: "RRF shines for hybrid retrieval: it is parameter-light and robust across datasets. Some practitioners report that a smaller k always improves quality [[blog_p0]], but that is dataset-dependent and not a general rule. It is sometimes claimed that RRF requires labelled training data [[wiki_p0]] — it does not; RRF is unsupervised and uses only rank positions.", cited_passage_ids: ["blog_p0", "wiki_p0"], }, { kind: "table", id: "b4", caption: "RRF vs. learning-to-rank, at a glance", columns: ["", "RRF", "Learning-to-rank"], rows: [ ["Needs labels", "No", "Yes"], ["Score normalization", "Not required", "Required"], ["Tuning surface", "Just k", "Features + model"], ], }, ], claims, passages, all_hits, unsupported_count: 1, follow_ups: [ "How is k chosen in practice?", "RRF vs. weighted score fusion — when does each win?", "Does RRF work for more than two result lists?", ], };
